// Event defines model for Event.
type Event struct {
	Attributes *EventAttributes   `json:"attributes,omitempty"`
	CameraId   openapi_types.UUID `json:"camera_id"`
	CameraName string             `json:"camera_name"`

	// EndTime Null while the event is in progress.
	EndTime *time.Time `json:"end_time,omitempty"`

	// HasPreview The VMS has copied this event's preview clip to central storage (an OpenVMS-internal signal, not a probe of Frigate's own preview availability).
	HasPreview bool `json:"has_preview"`

	// HasSnapshot Frigate reported a saved snapshot for at least one detection of this event.
	HasSnapshot bool `json:"has_snapshot"`

	// HasThumbnail The VMS keeps its own copy of the thumbnail.
	HasThumbnail bool               `json:"has_thumbnail"`
	Id           openapi_types.UUID `json:"id"`
	Labels       []string           `json:"labels"`

	// Plates Normalized plates read during the event. Empty without lpr.view.
	Plates []string `json:"plates"`

	// RemoteId Review id inside the origin Frigate.
	RemoteId   string             `json:"remote_id"`
	Reviewed   bool               `json:"reviewed"`
	ServerId   openapi_types.UUID `json:"server_id"`
	ServerName string             `json:"server_name"`
	Severity   Severity           `json:"severity"`
	SiteId     openapi_types.UUID `json:"site_id"`
	SiteName   string             `json:"site_name"`
	StartTime  time.Time          `json:"start_time"`

	// SubLabels On LPR-capable cameras, recognized plate text (empty without lpr.view). On other cameras, an ordinary event field (e.g. a recognized face name) visible under normal events.view.
	SubLabels []string           `json:"sub_labels"`
	TenantId  openapi_types.UUID `json:"tenant_id"`

	// Tracks Tracked objects of this event as reported by Frigate. Empty when none were recorded.
	Tracks []ObjectTrack `json:"tracks"`
	Zones  []string      `json:"zones"`
}

